// ============================================
// VALIDATION INPUT - MCP Documents Process
// RFC-014 Compliant with Optional Tracing Fields
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, no validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required fields ---
const jobId = body.job_id || ctx.job_id;
const fileUrl = ctx.file_url || body.file_url;
const fileBase64 = ctx.file_base64 || body.file_base64;

if (!jobId) {
  errors.push('job_id required');
}
if (!fileUrl && !fileBase64) {
  errors.push('file_url or file_base64 required');
}

// --- Optional parameters with defaults ---
const fileType = ctx.file_type || body.file_type || 'pdf';
const action = body.action || ctx.action || 'translate';
const params = body.params || ctx.params || {};
const pluginContext = body.plugin_context || ctx.plugin_context || {};
const callbackUrl = body.callback_url || ctx.callback_url;
const conversationId = body.conversation_id || ctx.conversation_id;
const channelId = body.channel_id || ctx.channel_id;

// Verify custom action webhook URL if applicable
const customActions = pluginContext?.custom_actions || {};
const isCustomAction = Object.keys(customActions).includes(action);
const customWebhookUrl = isCustomAction ? customActions[action]?.webhook_url : null;

if (isCustomAction && !customWebhookUrl) {
  errors.push(`Custom action '${action}' has no webhook_url configured`);
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    job_id: jobId
  };
}

// Build context object
const context = {
  job_id: jobId,
  conversation_id: conversationId,
  user_id: userId,
  guild_id: guildId,
  channel_id: channelId,
  file_url: fileUrl,
  file_base64: fileBase64,
  file_type: fileType,
  action: action,
  params: params,
  plugin_context: pluginContext,
  callback_url: callbackUrl,
  start_time: Date.now()
};

return {
  valid: true,
  context: context,
  is_custom_action: isCustomAction,
  custom_webhook_url: customWebhookUrl,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  job_id: input.job_id,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'documents-process',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', ')
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// FORMAT CALLBACK with _trace
// ============================================

const result = $input.first().json;
const prevNode = $('Validate Input').first().json;
const context = prevNode.context;
const startTime = context.start_time;
const processingTime = Date.now() - startTime;

// Determine success or error
const isSuccess = result.success !== false && !result.error;
const hasData = result.data || result.text || result.result;

let callback;
let serviceResponse;

if (isSuccess && hasData) {
  // Success
  const text = result.data?.text || result.data?.translated_text || result.text || JSON.stringify(result.data || result);

  serviceResponse = {
    text: text,
    output_type: 'text',
    word_count: text.split(/\s+/).length,
    tokens_used: result.meta?.usage?.total_tokens || result.usage?.total_tokens || Math.ceil(text.length / 4),
    ocr_confidence: result.meta?.ocr_confidence || result.data?.ocr_confidence || 0.9,
    pages_processed: result.meta?.usage?.pages_processed || result.data?.page_count || 1
  };

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: true,
    result: {
      text: text,
      output_type: 'text',
      word_count: serviceResponse.word_count
    },
    metrics: {
      tokens_used: serviceResponse.tokens_used,
      processing_time_ms: processingTime,
      ocr_confidence: serviceResponse.ocr_confidence,
      pages_processed: serviceResponse.pages_processed
    },
    error: null,
    _trace: {
      service_response: serviceResponse,
      provider: 'documents-process',
      mode: 'success',
      latency_ms: processingTime,
      user_id: context.user_id,
      guild_id: context.guild_id,
      user_request: prevNode.user_request
    }
  };
} else {
  // Error
  const errorCode = result.error?.code || result.error?.status || 'INTERNAL_ERROR';
  const errorMessage = result.error?.message || 'Processing failed';

  serviceResponse = {
    error_code: errorCode,
    error_message: errorMessage
  };

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: false,
    result: null,
    metrics: {
      tokens_used: 0,
      processing_time_ms: processingTime,
      ocr_confidence: 0,
      pages_processed: 0
    },
    error: {
      code: errorCode,
      message: errorMessage,
      retriable: ['LLM_RATE_LIMITED', 'TIMEOUT', 'INTERNAL_ERROR'].includes(errorCode),
      refund: {
        recommended: true,
        percentage: errorCode === 'PARTIAL_SUCCESS' ? 50 : 100,
        reason: `Processing failed: ${errorMessage}`
      }
    },
    _trace: {
      service_response: serviceResponse,
      provider: 'documents-process',
      mode: 'error',
      latency_ms: processingTime,
      user_id: context.user_id,
      guild_id: context.guild_id,
      user_request: prevNode.user_request
    }
  };
}

return {
  json: {
    callback: callback,
    callback_url: context.callback_url
  }
};

// ============================================
// SEND CALLBACK
// ============================================

const input = $input.first().json;

// If no callback URL, log only
if (!input.callback_url) {
  return {
    json: {
      status: 'no_callback',
      callback: input.callback
    }
  };
}

// Send callback
try {
  const response = await fetch(input.callback_url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input.callback)
  });

  return {
    json: {
      status: 'callback_sent',
      callback_status: response.status,
      callback: input.callback
    }
  };
} catch (error) {
  return {
    json: {
      status: 'callback_failed',
      error: error.message,
      callback: input.callback
    }
  };
}

